from g import *
# 05
A('05', 'reply-classifier', 'Cold-email reply classifier', 'Sales', 'Classifies replies to your outreach (interested, not now, unsubscribe, out of office), alerts you on interested ones and keeps a clean list.',
 ('webhook', 'email-reply'), [cfg(), norm("return [{json:{from:b.from,subject:b.subject||'',text:String(b.text||'').slice(0,2000)}}];"),
  ai('Classify reply', 'Classify the email reply to a sales outreach. JSON: {"label":"interested|not_now|unsubscribe|out_of_office|question","summary":"short","suggested_reply":"short draft"}', "JSON.stringify($json)"),
  iff("['interested','question'].includes($json.ai.label)", [slack('Alert: positive reply', "'Reply from ' + $json.from + ' [' + $json.ai.label + ']: ' + $json.ai.summary + ' Draft: ' + $json.ai.suggested_reply")], [row('Row: other', "return [{json:{date:new Date().toISOString(),from:j.from,label:j.ai.label}}];"), sheet_append('Log other replies')])],
 {'from': 'sam@client.com', 'subject': 'Re: quick question', 'text': 'This looks interesting, can you send pricing?'}, SETUP_STD, {'AI: Classify reply': {'label': 'interested', 'summary': 'Asks for pricing', 'suggested_reply': 'Happy to, here it is...'}}, ['Alert: positive reply'], ['Log other replies'])
# 06
A('06', 'pre-call-brief', 'Meeting booked: AI pre-call brief', 'Sales', 'When someone books a call (Calendly or Cal.com webhook) it builds a short brief from their form answers and sends it to Slack before the call.',
 ('webhook', 'meeting-booked'), [cfg(), norm("const p=b.payload||b;return [{json:{name:p.name||'Guest',email:p.email,start:p.scheduled_event?p.scheduled_event.start_time:p.start,answers:JSON.stringify(p.questions_and_answers||p.answers||[])}}];"),
  ai('Brief', 'Write a pre-call brief for a salesperson. JSON: {"brief":"3 bullet points","questions":["3 discovery questions"],"risk":"one watch-out"}', "JSON.stringify($json)"),
  slack('Send brief', "'Call with ' + $json.name + ' at ' + $json.start + '\\n' + $json.ai.brief + '\\nAsk: ' + $json.ai.questions.join(' | ') + '\\nWatch: ' + $json.ai.risk")],
 {'payload': {'name': 'Priya Shah', 'email': 'priya@co.com', 'scheduled_event': {'start_time': '2026-12-01T15:00:00Z'}, 'questions_and_answers': [{'q': 'Goal', 'a': 'cut churn'}]}}, SETUP_STD, {'AI: Brief': {'brief': '- A\n- B\n- C', 'questions': ['Q1', 'Q2', 'Q3'], 'risk': 'Budget unclear'}}, ['Send brief'])
# 07
A('07', 'proposal-nudger', 'Proposal follow-up nudger', 'Sales', 'Daily check of sent proposals. Emails the client on day 3 and day 7 and warns you on day 14.',
 cron(9, 30), [cfg(), sheet_read('Read proposals'),
  code('Pick nudges', "const now=Date.now();const out=[];for(const it of $input.all()){const r=it.json;if(r.status!=='Sent')continue;const age=Math.floor((now-new Date(r.sent_on).getTime())/864e5);if([3,7,14].includes(age))out.push({json:{client:r.client,email:r.email,title:r.title,age,stage:age===14?'final':age===7?'second':'first'}});}return out;"),
  iff("$json.stage !== 'final'", [mail('Nudge client', '$json.email', "'Any questions on ' + $json.title + '?'", "'Hi ' + $json.client + ',\\n\\nJust checking you received the proposal for ' + $json.title + ' (sent ' + $json.age + ' days ago). Happy to jump on a quick call.\\n\\n' + $('Config').first().json.businessName")], [slack('Warn: stale proposal', "$json.client + ' has not answered ' + $json.title + ' in ' + $json.age + ' days. Time to call or close out.'")])],
 {}, ['Sheet columns: client, email, title, status, sent_on (YYYY-MM-DD).'] + SETUP_STD[1:], {'Read proposals': [{'client': 'A', 'email': 'a@a.com', 'title': 'Website', 'status': 'Sent', 'sent_on': '__AGO3__'}, {'client': 'B', 'email': 'b@b.com', 'title': 'SEO', 'status': 'Sent', 'sent_on': '__AGO14__'}, {'client': 'C', 'email': 'c@c.com', 'title': 'X', 'status': 'Won', 'sent_on': '__AGO3__'}]}, ['Nudge client', 'Warn: stale proposal'])
# 08
A('08', 'stripe-onboarding', 'Payment received: client onboarding kickoff', 'Sales', 'On a successful Stripe checkout it sends a welcome email with next steps, alerts the team and logs the customer.',
 ('webhook', 'stripe-paid'), [cfg(onboardingLink='https://calendly.com/you/kickoff'), norm("const o=(b.data&&b.data.object)||b;const d=o.customer_details||{};return [{json:{event:b.type||'checkout.session.completed',name:d.name||o.customer_name||'there',email:d.email||o.customer_email,amount:(Number(o.amount_total||o.amount||0)/100),currency:String(o.currency||'usd').toUpperCase()}}];"),
  iff("$json.event === 'checkout.session.completed' && $json.email", [mail('Welcome email', '$json.email', "'Welcome to ' + $('Config').first().json.businessName", "'Hi ' + $json.name + ',\\n\\nThank you for your payment of ' + $json.amount.toFixed(2) + ' ' + $json.currency + '. Book your kickoff call here: ' + $('Config').first().json.onboardingLink + '\\n\\n' + $('Config').first().json.businessName"), slack('Alert: new customer', "'New customer ' + $json.name + ' paid ' + $json.amount.toFixed(2) + ' ' + $json.currency"), row('Row: customer', "return [{json:{date:new Date().toISOString(),name:j.name,email:j.email,amount:j.amount,currency:j.currency}}];"), sheet_append('Log customer')])],
 {'type': 'checkout.session.completed', 'data': {'object': {'amount_total': 29700, 'currency': 'usd', 'customer_details': {'name': 'Leo Grant', 'email': 'leo@x.com'}}}}, ['Add the webhook URL in Stripe > Developers > Webhooks for checkout.session.completed.'] + SETUP_STD[1:], {}, ['Welcome email', 'Alert: new customer', 'Log customer'])
# 09
A('09', 'review-request', 'Review request after purchase', 'Marketing', 'Waits two days after an order is delivered, then asks for a Google review; happy customers go to the public link, others to a private feedback form.',
 ('webhook', 'order-delivered'), [cfg(reviewLink='https://g.page/r/YOUR_ID/review', feedbackLink='https://yourdomain.com/feedback'), norm("return [{json:{name:b.name||'there',email:b.email,order:b.order_id||'',rating:Number(b.rating||0)}}];"), wait('Wait 2 days', 2, 'days'),
  iff('$json.rating === 0 || $json.rating >= 4', [mail('Ask for review', '$json.email', "'How did we do, ' + $json.name + '?'", "'Hi ' + $json.name + ',\\n\\nIf you enjoyed order ' + $json.order + ', would you leave a quick review? ' + $('Config').first().json.reviewLink + '\\n\\nThank you!'")], [mail('Ask for private feedback', '$json.email', "'Can we make it right?'", "'Hi ' + $json.name + ',\\n\\nSorry the experience was not perfect. Tell us what happened: ' + $('Config').first().json.feedbackLink")])],
 {'name': 'Ella', 'email': 'ella@x.com', 'order_id': 'A100', 'rating': 5}, SETUP_STD, {}, ['Ask for review'], ['Ask for private feedback'])
# 10
A('10', 'abandoned-cart', 'Abandoned cart recovery with AI email', 'Ecommerce', 'Shopify or WooCommerce abandoned-checkout webhook, one-hour wait, then a personalised AI recovery email with the cart contents and optional discount for big carts.',
 ('webhook', 'abandoned-cart'), [cfg(discountCode='COMEBACK10', discountOver='80'), norm("const items=(b.line_items||[]).map(i=>i.title+' x'+i.quantity);return [{json:{name:b.name||b.customer&&b.customer.first_name||'there',email:b.email,items:items.join(', '),total:Number(b.total_price||0),url:b.abandoned_checkout_url||''}}];"), wait('Wait 1 hour', 1, 'hours'),
  code('Decide offer', "const j=$input.first().json;const c=$('Config').first().json;return [{json:{...j,offer:j.total>=Number(c.discountOver)?c.discountCode:''}}];"),
  ai('Recovery email', 'Write a short friendly cart-recovery email. No fake urgency. JSON: {"subject":"","body":""}. Mention the offer code only if given.', "JSON.stringify({name:$json.name,items:$json.items,offer:$json.offer,url:$json.url})"),
  mail('Send recovery email', "$('Normalize').first().json.email", '$json.ai.subject', "$json.ai.body + '\\n\\nFinish your order: ' + $json.url")],
 {'name': 'Jo', 'email': 'jo@x.com', 'line_items': [{'title': 'Linen shirt', 'quantity': 2}], 'total_price': '120.00', 'abandoned_checkout_url': 'https://shop.com/cart/abc'}, SETUP_STD, {'AI: Recovery email': {'subject': 'You left something behind', 'body': 'Hi Jo, your linen shirts are waiting. Use COMEBACK10.'}}, ['Send recovery email'])
# 11
A('11', 'support-triage', 'AI support ticket triage', 'Support', 'Classifies each ticket (billing, bug, how-to, feature, cancel), sets priority, drafts a reply and pages Slack for urgent ones.',
 ('webhook', 'support-ticket'), [cfg(), norm("return [{json:{id:b.id||b.ticket_id,email:b.email,subject:b.subject||'',message:String(b.message||b.body||'').slice(0,3000)}}];"),
  ai('Triage', 'You are a support lead. JSON: {"category":"billing|bug|how_to|feature|cancel|other","priority":"low|normal|urgent","sentiment":"positive|neutral|angry","draft":"a helpful reply"}', "JSON.stringify($json)"),
  iff("$json.ai.priority === 'urgent' || $json.ai.sentiment === 'angry'", [slack('Page: urgent ticket', "'URGENT #' + $json.id + ' [' + $json.ai.category + '] ' + $json.subject + '\\nDraft: ' + $json.ai.draft")], [row('Row: ticket', "return [{json:{id:j.id,email:j.email,category:j.ai.category,priority:j.ai.priority,draft:j.ai.draft}}];"), sheet_append('Log ticket')])],
 {'id': 4021, 'email': 'sam@x.com', 'subject': 'Charged twice!!', 'message': 'You charged me twice and nobody answers. Refund now.'}, SETUP_STD, {'AI: Triage': {'category': 'billing', 'priority': 'urgent', 'sentiment': 'angry', 'draft': 'Sorry, we are refunding the duplicate.'}}, ['Page: urgent ticket'], ['Log ticket'])
# 12
A('12', 'faq-auto-answer', 'FAQ auto-answer with your own knowledge base', 'Support', 'Matches a customer question against your FAQ list first (no AI cost), then lets AI answer only from the matched entries and escalates when unsure.',
 ('webhook', 'ask'), [cfg(), norm("return [{json:{email:b.email,question:String(b.question||'')}}];"), sheet_read('Read FAQ'),
  code('Match FAQ', "const q=$('Normalize').first().json.question.toLowerCase().split(/\\W+/).filter(w=>w.length>3);const scored=$input.all().map(i=>i.json).map(r=>{const t=(r.question+' '+r.answer).toLowerCase();return {r,s:q.filter(w=>t.includes(w)).length};}).filter(x=>x.s>0).sort((a,b)=>b.s-a.s).slice(0,3);return [{json:{...$('Normalize').first().json,matches:scored.map(x=>x.r),found:scored.length>0}}];"),
  iff('$json.found', [code('Normalize', "return [{json:$input.first().json}];") if False else row('Prep answer', "return [{json:j}];"), N('AI: Answer', 'n8n-nodes-base.httpRequest', 4.2, {'method': 'POST', 'url': "={{ $('Config').first().json.aiBaseUrl }}", 'authentication': 'genericCredentialType', 'genericAuthType': 'httpHeaderAuth', 'sendBody': True, 'specifyBody': 'json', 'jsonBody': "={{ JSON.stringify({model:$('Config').first().json.aiModel,messages:[{role:'system',content:'Answer ONLY using the FAQ entries given. If they do not answer the question, reply exactly: ESCALATE.'},{role:'user',content:JSON.stringify({question:$json.question,faq:$json.matches})}]}) }}", 'options': {}}, {'httpHeaderAuth': {'id': '', 'name': 'AI API key (Header Auth)'}}),
   mail('Email answer', "$('Normalize').first().json.email", "'Re: your question'", "$json.choices[0].message.content")], [slack('Escalate: no FAQ match', "'No FAQ match for: ' + $json.question + ' from ' + $json.email")])],
 {'email': 'amy@x.com', 'question': 'How long does shipping take to Canada?'}, ['Sheet columns: question, answer.'] + SETUP_STD[1:], {'Read FAQ': [{'question': 'Shipping time', 'answer': 'US 3 days, Canada 5-7 days'}, {'question': 'Returns', 'answer': '30 days'}], 'AI: Answer': 'Canada orders take 5-7 days.'}, ['Email answer'], ['Escalate: no FAQ match'])
